def orientations(P):
    outs=[]
    for refl in [False,True]:
        Q={(r, -c if refl else c) for r,c in P}
        for k in range(4):
            # rotate cw k times (r,c)->(c,-r)
            R=Q
            for _ in range(k): R={(c,-r) for r,c in R}
            mn_r=min(r for r,c in R); mn_c=min(c for r,c in R)
            norm=frozenset((r-mn_r,c-mn_c) for r,c in R)
            if norm not in [x[0] for x in outs]: outs.append((norm,(refl,k)))
    return outs
for P,label in [(O3,'out')]:
