from collections import deque

def comps8(S):
    S=set(S); res=[]
    while S:
        p=S.pop(); comp={p}; q=[p]
        while q:
            r,c=q.pop()
            for dr in [-1,0,1]:
                for dc in [-1,0,1]:
                    np=(r+dr,c+dc)
                    if (dr or dc) and np in S:
                        S.remove(np); comp.add(np); q.append(np)
        res.append(comp)
    return sorted(res,key=len,reverse=True)
